"use client"

import * as React from "react"
import { CheckIcon, ChevronRightIcon } from "lucide-react"
import { DropdownMenu as DropdownMenuPrimitive } from "radix-ui"

import { Checkbox } from "@/components/cubix/radix/checkbox"
import { RadioGroup, RadioGroupItem } from "@/components/cubix/radix/radio-group"
import { DirectionProvider } from "@/components/cubix/radix/direction"
import { cn } from "@/lib/utils"

type TextDirection = "ltr" | "rtl"

type DropdownMenuLocale = {
  dir?: TextDirection
  lang?: string
}

const DropdownMenuLocaleContext = React.createContext<DropdownMenuLocale>({})

const DropdownMenuLocaleResolverContext = React.createContext<
  ((locale: DropdownMenuLocale) => void) | null
>(null)

function useDropdownMenuLocale() {
  return React.useContext(DropdownMenuLocaleContext)
}

function toTextDirection(value: string | null | undefined): TextDirection | undefined {
  return value === "rtl" || value === "ltr" ? value : undefined
}

function resolveClosestDir(node: Element | null): TextDirection | undefined {
  return toTextDirection(node?.closest("[dir]")?.getAttribute("dir"))
}

function resolveClosestLang(node: Element | null): string | undefined {
  return node?.closest("[lang]")?.getAttribute("lang") ?? undefined
}

type DropdownMenuStore = Map<string, unknown>

const DropdownMenuStoreContext = React.createContext<DropdownMenuStore | null>(null)

function textContent(node: React.ReactNode): string {
  if (node == null || typeof node === "boolean") return ""
  if (typeof node === "string" || typeof node === "number") return String(node)
  if (Array.isArray(node)) return node.map(textContent).join("")
  if (React.isValidElement<{ children?: React.ReactNode }>(node)) {
    return textContent(node.props.children)
  }
  return ""
}

function radioGroupKey(children: React.ReactNode) {
  const values: string[] = []
  React.Children.forEach(children, (child) => {
    if (React.isValidElement<{ value?: unknown }>(child) && child.props.value !== undefined) {
      values.push(String(child.props.value))
    }
  })
  return `radio:${values.join("|")}`
}

/*
  Menu content unmounts when the menu closes, so uncontrolled checkbox and
  radio state is kept on the root (keyed by the item label or the group's
  item values) and survives reopening the menu.
*/
function usePersistentState<T>(key: string, initial: T) {
  const store = React.useContext(DropdownMenuStoreContext)
  const [value, setValue] = React.useState<T>(() =>
    store?.has(key) ? (store.get(key) as T) : initial
  )
  const update = React.useCallback(
    (next: T) => {
      store?.set(key, next)
      setValue(next)
    },
    [store, key]
  )
  return [value, update] as const
}

function localeDomProps(locale: DropdownMenuLocale) {
  return {
    ...(locale.dir ? { dir: locale.dir } : {}),
    ...(locale.lang ? { lang: locale.lang } : {}),
  }
}

/*
  The root renders no element, so the trigger reports the closest dir / lang
  from the page and the root shares it with the portaled content. Explicit
  dir / lang props on the root always win.
*/
function DropdownMenu({
  dir,
  lang,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Root> & {
  lang?: string
}) {
  const [store] = React.useState<DropdownMenuStore>(() => new Map())
  const [resolved, setResolved] = React.useState<DropdownMenuLocale>({})
  const resolvedDir = resolved.dir
  const resolvedLang = resolved.lang
  const locale = React.useMemo<DropdownMenuLocale>(
    () => ({
      dir: toTextDirection(dir) ?? resolvedDir,
      lang: lang ?? resolvedLang,
    }),
    [dir, lang, resolvedDir, resolvedLang]
  )

  return (
    <DropdownMenuStoreContext.Provider value={store}>
      <DropdownMenuLocaleResolverContext.Provider value={setResolved}>
        <DropdownMenuLocaleContext.Provider value={locale}>
          <DirectionProvider dir={locale.dir ?? "ltr"}>
            <DropdownMenuPrimitive.Root data-slot="dropdown-menu" dir={locale.dir} {...props} />
          </DirectionProvider>
        </DropdownMenuLocaleContext.Provider>
      </DropdownMenuLocaleResolverContext.Provider>
    </DropdownMenuStoreContext.Provider>
  )
}

function DropdownMenuPortal({
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Portal>) {
  return <DropdownMenuPrimitive.Portal data-slot="dropdown-menu-portal" {...props} />
}

function DropdownMenuTrigger({
  ref,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Trigger>) {
  const locale = useDropdownMenuLocale()
  const reportLocale = React.useContext(DropdownMenuLocaleResolverContext)
  const triggerRef = React.useRef<HTMLButtonElement | null>(null)
  const setTriggerRef = React.useCallback(
    (node: HTMLButtonElement | null) => {
      triggerRef.current = node
      if (typeof ref === "function") ref(node)
      else if (ref) ref.current = node
    },
    [ref]
  )

  React.useLayoutEffect(() => {
    const parent = triggerRef.current?.parentElement ?? null
    reportLocale?.({
      dir: resolveClosestDir(parent),
      lang: resolveClosestLang(parent),
    })
  }, [reportLocale])

  return (
    <DropdownMenuPrimitive.Trigger
      ref={setTriggerRef}
      data-slot="dropdown-menu-trigger"
      {...localeDomProps(locale)}
      {...props}
    />
  )
}

function DropdownMenuContent({
  className,
  align = "start",
  sideOffset = 4,
  dir,
  lang,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Content> & {
  dir?: TextDirection
  lang?: string
}) {
  const locale = useDropdownMenuLocale()
  const contentLocale = {
    dir: toTextDirection(dir) ?? locale.dir,
    lang: lang ?? locale.lang,
  }

  return (
    <DropdownMenuPortal>
      <DropdownMenuPrimitive.Content
        data-slot="dropdown-menu-content"
        sideOffset={sideOffset}
        align={align}
        className={cn(
          "z-50 max-h-(--radix-dropdown-menu-content-available-height) w-max min-w-[150px] origin-(--radix-dropdown-menu-content-transform-origin) overflow-x-visible overflow-y-auto rounded-lg bg-popover p-1 text-start text-popover-foreground shadow-md ring-1 ring-foreground/[0.06] duration-100 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95 data-[state=closed]:animate-out data-[state=closed]:overflow-hidden data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95",
          className
        )}
        {...localeDomProps(contentLocale)}
        {...props}
      />
    </DropdownMenuPortal>
  )
}

function DropdownMenuGroup({ ...props }: React.ComponentProps<typeof DropdownMenuPrimitive.Group>) {
  return <DropdownMenuPrimitive.Group data-slot="dropdown-menu-group" {...props} />
}

function DropdownMenuItem({
  className,
  inset,
  variant = "default",
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Item> & {
  inset?: boolean
  variant?: "default" | "destructive"
}) {
  return (
    <DropdownMenuPrimitive.Item
      data-slot="dropdown-menu-item"
      data-inset={inset}
      data-variant={variant}
      className={cn(
        "group/dropdown-menu-item relative flex w-full cursor-default items-center gap-1.5 rounded-sm px-2 py-1.75 text-label whitespace-nowrap tracking-normal outline-hidden select-none focus:bg-accent focus:text-accent-foreground not-data-[variant=destructive]:focus:**:text-accent-foreground data-inset:ps-8 data-[variant=destructive]:text-destructive data-[variant=destructive]:focus:bg-destructive/10 data-[variant=destructive]:focus:text-destructive dark:data-[variant=destructive]:focus:bg-destructive/20 data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&>svg:not([class*='size-'])]:size-4.5 data-[variant=destructive]:*:[svg]:text-destructive!",
        className
      )}
      {...props}
    />
  )
}

type DropdownMenuIndicator = "check" | "control"

const DropdownMenuIndicatorContext = React.createContext<DropdownMenuIndicator | undefined>(
  undefined
)

function DropdownMenuCheckIndicator({ checked }: { checked: boolean }) {
  return (
    <span
      aria-hidden
      className="pointer-events-none absolute end-2 flex size-4 items-center justify-center"
    >
      {checked ? <CheckIcon absoluteStrokeWidth strokeWidth={1.6} className="size-4" /> : null}
    </span>
  )
}

/*
  Checkbox and radio items keep the menu open by default so several options
  can be changed in one go, matching the Base UI and React Aria menus. Pass
  closeOnClick to close the menu after a change.
*/
function keepOpenOnSelect(closeOnClick: boolean, onSelect?: (event: Event) => void) {
  return (event: Event) => {
    onSelect?.(event)
    if (!closeOnClick) event.preventDefault()
  }
}

function DropdownMenuCheckboxItem({
  className,
  children,
  checked,
  defaultChecked,
  onCheckedChange,
  onSelect,
  inset,
  indicator = "control",
  closeOnClick = false,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.CheckboxItem> & {
  inset?: boolean
  defaultChecked?: boolean
  indicator?: DropdownMenuIndicator
  closeOnClick?: boolean
}) {
  const [uncontrolledChecked, setUncontrolledChecked] = usePersistentState(
    `checkbox:${textContent(children)}`,
    defaultChecked ?? false
  )
  const isChecked = checked ?? uncontrolledChecked

  return (
    <DropdownMenuPrimitive.CheckboxItem
      data-slot="dropdown-menu-checkbox-item"
      data-inset={inset}
      className={cn(
        "relative flex w-full cursor-default items-center gap-1.5 rounded-sm py-1.75 ps-2 pe-10 text-label whitespace-nowrap tracking-normal outline-hidden select-none focus:bg-accent focus:text-accent-foreground data-inset:ps-8 data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&>svg:not([class*='size-'])]:size-4.5",
        className
      )}
      checked={isChecked}
      onCheckedChange={(value) => {
        if (checked === undefined) setUncontrolledChecked(value)
        onCheckedChange?.(value)
      }}
      onSelect={keepOpenOnSelect(closeOnClick, onSelect)}
      {...props}
    >
      {indicator === "check" ? (
        <DropdownMenuCheckIndicator checked={isChecked === true} />
      ) : (
        <span
          aria-hidden
          className="pointer-events-none absolute end-2 flex items-center justify-center"
        >
          <Checkbox
            className="size-3.5 rounded-[4px] [&_[data-slot=checkbox-indicator]_svg]:size-2.5"
            checked={isChecked === true}
            tabIndex={-1}
          />
        </span>
      )}
      {children}
    </DropdownMenuPrimitive.CheckboxItem>
  )
}

const DropdownMenuRadioValueContext = React.createContext<string | undefined>(undefined)

function DropdownMenuRadioGroup({
  value,
  defaultValue,
  onValueChange,
  indicator,
  children,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.RadioGroup> & {
  defaultValue?: string
  indicator?: DropdownMenuIndicator
}) {
  const [uncontrolledValue, setUncontrolledValue] = usePersistentState<string | undefined>(
    radioGroupKey(children),
    defaultValue
  )
  const currentValue = value ?? uncontrolledValue

  return (
    <DropdownMenuIndicatorContext.Provider value={indicator}>
      <DropdownMenuRadioValueContext.Provider value={currentValue}>
        <DropdownMenuPrimitive.RadioGroup
          data-slot="dropdown-menu-radio-group"
          value={currentValue ?? ""}
          onValueChange={(next) => {
            if (value === undefined) setUncontrolledValue(next)
            onValueChange?.(next)
          }}
          {...props}
        >
          {children}
        </DropdownMenuPrimitive.RadioGroup>
      </DropdownMenuRadioValueContext.Provider>
    </DropdownMenuIndicatorContext.Provider>
  )
}

function DropdownMenuRadioIndicator({ checked }: { checked: boolean }) {
  return (
    <span inert className="pointer-events-none absolute end-2 flex items-center justify-center">
      <RadioGroup value={checked ? "on" : ""} className="flex">
        <RadioGroupItem
          value="on"
          className="size-3.5 [&_[data-slot=radio-group-indicator]]:size-1.5"
        />
      </RadioGroup>
    </span>
  )
}

function DropdownMenuRadioItem({
  className,
  children,
  inset,
  value,
  indicator,
  onSelect,
  closeOnClick = false,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.RadioItem> & {
  inset?: boolean
  indicator?: DropdownMenuIndicator
  closeOnClick?: boolean
}) {
  const groupValue = React.useContext(DropdownMenuRadioValueContext)
  const groupIndicator = React.useContext(DropdownMenuIndicatorContext)
  const resolvedIndicator = indicator ?? groupIndicator ?? "control"
  const isChecked = groupValue !== undefined && groupValue === value

  return (
    <DropdownMenuPrimitive.RadioItem
      data-slot="dropdown-menu-radio-item"
      value={value}
      data-inset={inset}
      className={cn(
        "relative flex w-full cursor-default items-center gap-1.5 rounded-sm py-1.75 ps-2 pe-10 text-label whitespace-nowrap tracking-normal outline-hidden select-none focus:bg-accent focus:text-accent-foreground data-inset:ps-8 data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&>svg:not([class*='size-'])]:size-4.5",
        className
      )}
      onSelect={keepOpenOnSelect(closeOnClick, onSelect)}
      {...props}
    >
      {resolvedIndicator === "check" ? (
        <DropdownMenuCheckIndicator checked={isChecked} />
      ) : (
        <DropdownMenuRadioIndicator checked={isChecked} />
      )}
      {children}
    </DropdownMenuPrimitive.RadioItem>
  )
}

function DropdownMenuLabel({
  className,
  inset,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Label> & {
  inset?: boolean
}) {
  return (
    <DropdownMenuPrimitive.Label
      data-slot="dropdown-menu-label"
      data-inset={inset}
      className={cn(
        "px-2 py-1 text-caption text-muted-foreground whitespace-nowrap font-medium tracking-normal data-inset:ps-8",
        className
      )}
      {...props}
    />
  )
}

function DropdownMenuSeparator({
  className,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Separator>) {
  return (
    <DropdownMenuPrimitive.Separator
      data-slot="dropdown-menu-separator"
      className={cn("-mx-1 my-1 h-px bg-border/60", className)}
      {...props}
    />
  )
}

/*
  The shortcut keeps the item's direction so ms-auto / ps-4 place it at the
  inline end, while the keys themselves read left to right (⇧⌘P, not P⌘⇧).
*/
function DropdownMenuShortcut({ className, children, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="dropdown-menu-shortcut"
      className={cn(
        "ms-auto shrink-0 ps-4 font-mono text-caption tracking-normal whitespace-nowrap text-muted-foreground group-focus/dropdown-menu-item:text-accent-foreground",
        className
      )}
      {...props}
    >
      <span dir="ltr">{children}</span>
    </span>
  )
}

function DropdownMenuSub({ ...props }: React.ComponentProps<typeof DropdownMenuPrimitive.Sub>) {
  return <DropdownMenuPrimitive.Sub data-slot="dropdown-menu-sub" {...props} />
}

function DropdownMenuSubTrigger({
  className,
  inset,
  children,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.SubTrigger> & {
  inset?: boolean
}) {
  return (
    <DropdownMenuPrimitive.SubTrigger
      data-slot="dropdown-menu-sub-trigger"
      data-inset={inset}
      className={cn(
        "flex w-full cursor-default items-center gap-1.5 rounded-sm px-2 py-1.75 text-label whitespace-nowrap tracking-normal outline-none select-none focus:bg-accent focus:text-accent-foreground data-inset:ps-8 data-[state=open]:bg-accent data-[state=open]:text-accent-foreground data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&>svg:not([class*='size-'])]:size-4.5",
        className
      )}
      {...props}
    >
      {children}
      <span aria-hidden className="min-w-1 flex-1" />
      <ChevronRightIcon className="size-4 rtl:rotate-180" />
    </DropdownMenuPrimitive.SubTrigger>
  )
}

function DropdownMenuSubContent({
  className,
  alignOffset = -3,
  dir,
  lang,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.SubContent> & {
  dir?: TextDirection
  lang?: string
}) {
  const locale = useDropdownMenuLocale()
  const contentLocale = {
    dir: toTextDirection(dir) ?? locale.dir,
    lang: lang ?? locale.lang,
  }

  return (
    <DropdownMenuPortal>
      <DropdownMenuPrimitive.SubContent
        data-slot="dropdown-menu-sub-content"
        alignOffset={alignOffset}
        className={cn(
          "z-50 w-max min-w-[150px] origin-(--radix-dropdown-menu-content-transform-origin) overflow-x-visible rounded-lg bg-popover p-1 text-start text-popover-foreground shadow-lg ring-1 ring-foreground/[0.06] duration-100 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95",
          className
        )}
        {...localeDomProps(contentLocale)}
        {...props}
      />
    </DropdownMenuPortal>
  )
}

export {
  DropdownMenu,
  DropdownMenuPortal,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuLabel,
  DropdownMenuItem,
  DropdownMenuCheckboxItem,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuSub,
  DropdownMenuSubTrigger,
  DropdownMenuSubContent,
}
